'use client';

import { useSavingsData } from '@/hooks/data';
import { Card } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';

export default function Home() {
  // 1. Chiamiamo il nostro Custom Hook
  const { data, isLoading, isError } = useSavingsData();

  // 2. Gestiamo lo stato di caricamento
  if (isLoading) {
    return (
      <main className="p-8 max-w-6xl mx-auto">
        <p className="text-center text-lg">Caricamento dati di ottimizzazione in corso...</p>
      </main>
    );
  }

  // 3. Gestiamo lo stato di errore
  if (isError || !data) {
    return (
      <main className="p-8 max-w-6xl mx-auto">
        <p className="text-center text-lg text-red-500">
          Si è verificato un errore nel recupero dei dati. Riprova più tardi.
        </p>
      </main>
    );
  }

  // 4. Interfaccia principale con i dati caricati
  return (
    <main className="p-8 max-w-6xl mx-auto space-y-8">
      {/* Intestazione e Totale */}
      <header className="flex justify-between items-center pb-6 border-b border-[var(--color-border)]">
        <div>
          <h1 className="text-3xl font-bold">Cloud Savings Dashboard</h1>
          <p className="text-sm opacity-80">Ottimizzazione dei costi e sprechi infrastrutturali</p>
        </div>
        <Card className="text-right">
          <span className="text-xs uppercase tracking-wider block opacity-70">Risparmio Totale Stimato</span>
          <span className="text-2xl font-bold text-[var(--color-accent-primary)]">
            €{data.totalSavings.toLocaleString()}
          </span>
        </Card>
      </header>

      {/* Griglia delle Cards */}
      <section className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {data.metrics.map((metric) => (
          <Card key={metric.id} className="flex flex-col justify-between space-y-4">
            <div>
              <div className="flex justify-between items-start mb-2">
                <span className="text-xs font-mono opacity-60">{metric.category}</span>
                <Badge variant={metric.impactLevel === 'High' ? 'alert' : 'brand'}>
                  {metric.impactLevel} Impact
                </Badge>
              </div>
              <h2 className="text-lg font-semibold mb-2">{metric.title}</h2>
              <p className="text-sm opacity-80">{metric.description}</p>
            </div>

            <div className="pt-4 border-t border-[var(--color-border)] flex justify-between items-center">
              <span className="text-xs opacity-70">Risparmio:</span>
              <span className="text-lg font-bold">€{metric.savingsAmount}</span>
            </div>
          </Card>
        ))}
      </section>
    </main>
  );
}